const HISTORY: SubSection<"jobs" | "access" | "systemlog">[] = [
  { key: "jobs", label: "Server jobs", sub: "What we ran for you", icon: "activity" },
  { key: "access", label: "SSH access", sub: "Sign-ins and failures", icon: "key" },
  { key: "systemlog", label: "System log", sub: "Live read from the server", icon: "filesearch" },
];

export function VpsPanelShell({
  data, busy, suspendReason, provisionError,
  overviewPanel, consolePanel, filesPanel, servicesPanel,
  backupsPanel, snapshotsPanel, networkingPanel, settingsPanel,

"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { InsufficientBalanceError } from "./wallet";
import { resizeQuote, applyResize, ResizeError } from "./resize";
import { createResizeCheckout, type EmbeddedCheckout } from "./stripe";
import { walletSplit } from "./wallet-split";
import { emailVerificationError } from "./email-verification";
import { checkRateLimit } from "./rate-limit";
import { validateSubdomainFormat, isSubdomainAvailable } from "./game-subdomain";

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function queueJob(
  serverId: string,
  type:
    | "SNAPSHOT_CREATE"
    | "SNAPSHOT_DELETE"
    | "SNAPSHOT_ROLLBACK"
    | "BACKUP_CREATE"
    | "RESIZE"
    | "PASSWORD_RESET",
  payload?: Record<string, unknown>
): Promise<{ error?: string }> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };
  await db.job.create({ data: { type, serverId, payload: payload as any } });
  return {};
}

// ---------- Snapshots ----------

/**
 * The ONE snapshot-name normalisation, applied identically on every path.
 *
 * `worker/index.ts` snapshotOp re-applies exactly this (`[^a-zA-Z0-9_]` stripped,
 * 40 chars) and throws "snapshot: invalid name" on an empty result — so a name
 * this module accepts but the worker rejects is a job that reports QUEUED to the
 * customer and then dies in the worker with a message they never see. Delete and
 * rollback used to pass the raw argument straight through: a TypeScript parameter
 * type is not validation, and these are reachable with any string at all.
 */
function cleanSnapshotName(name: unknown): string {
  return String(name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
}

const SNAPSHOT_NAME_ERROR =
  "Snapshot name must be 2–40 characters of letters, digits or underscores. " +
  "Pick the snapshot from the list on the server page rather than typing its name.";

export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  const clean = cleanSnapshotName(name);
  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped." };
  }
  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  const clean = cleanSnapshotName(name);
  if (clean.length < 2) return { error: SNAPSHOT_NAME_ERROR };
  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name: clean });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${clean}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  const clean = cleanSnapshotName(name);
  if (clean.length < 2) return { error: SNAPSHOT_NAME_ERROR };
  // A rollback rewinds the VM's disk. The worker can only do that against a real
  // VM in a steady state — the same precondition createSnapshot already enforced.
  // Without it we accepted the request, said nothing, and let the job fail in the
  // worker while the customer believed their server was being restored.
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to roll back to a snapshot." };
  }
  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name: clean });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${clean}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

// ---------- Backups ----------

export async function createBackup(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped." };
  }
  const res = await queueJob(serverId, "BACKUP_CREATE");
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.backup_create", detail: serverId } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export type BackupJobStatus = {
  id: string;
  type: "BACKUP_CREATE" | "BACKUP_RESTORE";
  status: "QUEUED" | "RUNNING" | "DONE" | "FAILED";
  progress: number;
  step: string | null;
  error: string | null;
  createdAt: string;
};

/**
 * Return the most recent backup/restore job for a server so the UI can render a
 * live progress bar. Ownership-checked. Returns null if the server has never had
 * a backup/restore job. The client decides when to show the bar (in-flight) vs.
 * the completion/failure note.
 */
export async function getBackupJob(serverId: string): Promise<BackupJobStatus | null> {
  const { server } = await ownedServer(serverId);
  const job = await db.job.findFirst({
    where: { serverId: server.id, type: { in: ["BACKUP_CREATE", "BACKUP_RESTORE"] } },
    orderBy: { createdAt: "desc" },
    select: { id: true, type: true, status: true, progress: true, step: true, error: true, createdAt: true },
  });
  if (!job) return null;
  return {
    id: job.id,
    type: job.type as BackupJobStatus["type"],
    status: job.status as BackupJobStatus["status"],
    progress: job.progress,
    step: job.step,
    error: job.error,
    createdAt: job.createdAt.toISOString(),
  };
}

// ---------- Resize ----------

export async function resizeServer(
  serverId: string,
  planId: string,
  useWallet: boolean = true,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  // Spend path: an upgrade debits the wallet (and can open a Stripe Checkout in
  // the customer's name), so it carries the same impersonation guard as every
  // other money movement — lib/actions-disk.ts expandServerDisk, lib/actions.ts
  // payAndDeploy/topUp/renewNow, and the domain transfer actions.
  // This one was missed, which made "upgrade the plan" the one charge an admin
  // impersonating a customer could still put on that customer's balance.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  // Purchase gate: an upgrade is a charge (wallet or card). Downgrades live in
  // resizeServerDown and are deliberately NOT gated — that path REFUNDS, and
  // stopping a customer from spending LESS would be a gate with no one to
  // protect. See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Validate + price the upgrade (ownership already checked above). resizeQuote
  // recomputes the exact prorated charge over the remaining term.
  let quote;
  try {
    quote = await resizeQuote(serverId, planId);
  } catch (e) {
    if (e instanceof ResizeError) return { error: e.message };
    throw e;
  }
  const { newPlan, prorateCents } = quote;

  // Wallet-aware split — identical logic to the deploy flow. ResizePicker computes
  // the same split (lib/wallet-split.ts) so displayed === charged.
  const { cardCents } = walletSplit({
    dueCents: prorateCents,
    balanceCents: user.balanceCents,
    useWallet,
  });

  // Card portion > 0 → charge ONLY the remainder on the card (not the full
  // proration). The confirm route credits the card amount to the wallet and then
  // debits the FULL proration (encoded as chargeCents), so the wallet absorbs its
  // share and the card the rest — wallet never touched before the card clears.
  if (cardCents > 0) {
    const checkout = await createResizeCheckout(user, cardCents, {
      serverId,
      planId,
      planName: newPlan.name,
      prorateCents,
    });
    if (!checkout) {
      return {
        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
      };
    }
    return { checkout };
  }

  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
  // servers) → apply instantly, debiting the full proration from the wallet.
  try {
    await applyResize({ serverId, planId, actorUserId: user.id });
  } catch (e) {
    if (e instanceof ResizeError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- Root password reset ----------

export async function resetRootPassword(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to reset its password." };
  }
  const res = await queueJob(serverId, "PASSWORD_RESET");
  if (!res.error) {
    await db.auditLog.create({
      data: { userId: user.id, action: "server.password_reset", detail: serverId },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    revalidatePath(`/admin/servers/${serverId}`);
  }
  return res;
}

// ---------- Port forwarding (firewall/networking) ----------

import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
const MAX_FORWARDS_PER_SERVER = 10;

export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
  const serverId = String(formData.get("serverId") ?? "");
  const { user, server } = await ownedServer(serverId);
  const parsed = z
    .object({
      guestPort: z.coerce.number().int().min(1).max(65535),
      protocol: z.enum(["tcp", "udp"]),

      protocol: z.enum(["tcp", "udp"]),
    })
    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
  if (!parsed.success) return { error: "Invalid port." };

  const count = await db.portForward.count({ where: { serverId } });
  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };

  // Allocate the public port with the DB as the arbiter, not this read.
  //
  // `PortForward.publicPort` is UNIQUE (prisma/schema.prisma). Choosing a port
  // from a snapshot read and inserting it unguarded meant two requests that
  // overlapped — a double-click, or two customers adding a forward at the same
  // moment — both picked the same lowest free port and the loser's insert threw
  // a raw Prisma P2002. That exception escaped this action, so the customer got
  // a server-error page instead of a message, and (in production, where Next
  // redacts action errors) no clue what happened or that simply retrying works.
  //
  // Retry across the next few free candidates so an ordinary collision resolves
  // itself silently, and turn a genuine exhaustion into an honest, actionable
  // message rather than a crash.
  const used = new Set([
    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
  ]);
  const candidates: number[] = [];
  for (let p = PF_MIN; p <= PF_MAX && candidates.length < 8; p++) {
    if (!used.has(p)) candidates.push(p);
  }
  if (candidates.length === 0) {
    return {
      error:
        "Every public port in the forwarding pool is in use, so we can't allocate one for this rule. " +
        "Delete a forward you no longer need, or contact support to have the pool widened.",
    };
  }

  let publicPort = 0;
  for (const candidate of candidates) {
    try {
      await db.portForward.create({
        data: { serverId, publicPort: candidate, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
      });
      publicPort = candidate;
      break;
    } catch (e: any) {
      // P2002 = another request took this port between our read and this insert.
      // Anything else is a real failure and must not be swallowed.
      if (e?.code !== "P2002") throw e;
    }
  }
  if (!publicPort) {
    return {
      error:
        "Another request took the public port we picked, several times in a row. " +
        "Nothing was created — please try adding the forward again.",
    };
  }

  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
  // A NAT Minecraft server's game port isn't forwarded until this moment (see
  // worker/index.ts's provision() comment) — this may be the first time its
  // subdomain DNS has anything valid to point at.
  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

export async function deletePortForward(serverId: string, forwardId: string) {
  const { user } = await ownedServer(serverId);
  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
  // If this was the game's forward, the subdomain has nothing to point at anymore.
  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
}

/**
 * Rename a paid Minecraft server's `<subdomain>.play.nxeon.cloud`. Mirrors
 * lib/actions-free-minecraft.ts's changeFreeMinecraftSubdomain: format/reserved
 * check, then let the DB's unique constraint (Server.subdomain) catch the
 * same-table race rather than a separate findFirst-then-update (TOCTOU).
 */
export async function changeGameSubdomain(prev: unknown, formData: FormData): Promise<{ error?: string }> {
  const serverId = String(formData.get("serverId") ?? "");
  const { user, server } = await ownedServer(serverId);

  const rl = checkRateLimit(`game:subdomain:${user.id}`, { max: 5, windowMs: 300_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)}m.` };

  const sub = String(formData.get("subdomain") ?? "").trim().toLowerCase();
  const formatError = validateSubdomainFormat(sub);
  if (formatError) return { error: formatError };
  if (sub === server.subdomain) return {};

  if (!(await isSubdomainAvailable(sub, { excludeServerId: serverId }))) {
    return { error: "That name is taken — try another." };
  }

  try {
    await db.server.update({ where: { id: serverId }, data: { subdomain: sub } });
  } catch (e: any) {
    if (e?.code === "P2002") return { error: "That name is taken — try another." };
    throw e;
  }

  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.game_subdomain_change", detail: `${serverId} -> ${sub}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

export async function serverAction(serverId: string, action: string): Promise<{ error?: string; jobId?: string } | void> {
  // Returns `{ error }` for anything the CUSTOMER can act on, so ServerControls
  // can render it — a `throw` here reaches the browser as Next's redacted generic
  // error, discarding the specific, actionable message (e.g. "Delete your data
  // volume(s) before reinstalling"). Only genuinely-impossible states still throw.
  // On success returns `{ jobId }` so the power controls
  // (components/customer/power/usePowerGuard.ts) can follow that exact job to
  // completion instead of guessing from a timer.
  const { user, server } = await ownedServer(serverId);
  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
    start: "START",
    stop: "STOP",
    reboot: "REBOOT",
    reinstall: "REINSTALL",
    delete: "DELETE",
  };
  const type = allowed[action];
  if (!type) throw new Error("Invalid action"); // not reachable from the UI — a real bug if it happens
  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
    return { error: "This server is suspended. Settle the outstanding balance to control it again." };
  }

  // A reinstall wipes the whole VM, including any block-storage volume the VM
  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
  //
  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
  // deliberately keeps `serverId` set so the volume can be re-attached
  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
  // Filtering on ATTACHED therefore missed the worst case: customer fills a
  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
  // Reinstall — both guards see zero attached volumes, and the purge takes the
  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
  // by serverId; this path did not. That asymmetry was the bug.
  if (type === "REINSTALL") {
    const pinnedVolumes = await db.volume.count({ where: { serverId } });
    if (pinnedVolumes > 0) {
      return {
        error:
          "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
      };
    }
  }

  // Check-then-enqueue under a per-server advisory lock. As a bare count()
  // followed by a separate create(), concurrent requests (two tabs, a
  // retrying client) each saw zero in-flight jobs and each enqueued — 10
  // simultaneous Reboots produced 3 REBOOT jobs on staging. See
  // lib/job-guard.ts.
  const queued = await withServerJobLock(serverId, async (tx) => {
    const pending = await tx.job.count({
      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (pending > 0) return null;
    if (type === "DELETE") {
      await tx.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
    }
    return tx.job.create({ data: { type, serverId }, select: { id: true } });
  });
  // Was a silent `return`: the customer clicked Start and nothing happened, ever,
  // with no explanation. Tell them why.
  if (!queued) return { error: "Another operation is already running on this server. Wait for it to finish." };

  await audit(user.id, `server.${action}`, serverId);
  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { jobId: queued.id };
}

// ---------- Wallet (demo top-up until a payment gateway is connected) ----------

export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
    const pending = await db.job.count({
      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
}

// ---------- Admin ----------

export async function adminExtendServer(prev: any, formData: FormData): Promise<{ error?: string }> {
  const admin = await requireAdmin();
  const serverId = String(formData.get("serverId") ?? "");
  const days = Number(formData.get("days"));
  if (!serverId || !Number.isFinite(days) || days === 0 || Math.abs(days) > 365) {
    return { error: "Days must be between -365 and 365." };
  }
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) return { error: "Server not found." };
  const base = server.expiresAt ? server.expiresAt.getTime() : Date.now();

  // ─── EXPIRESAT INTEGRITY ────────────────────────────────────────────────────
  // The whole proration model rests on "every month between now and `expiresAt` is
  // a month the customer has actually bought" (see lib/proration.ts
  // remainingMonths). This action moves `expiresAt` by up to a year per call, with
  // no call limit and no payment — so before the persisted rate existed, an admin
  // goodwill gift of 12 months was directly convertible to cash: downgrade the
  // gifted server and the prorated credit paid out real wallet money for months
  // nobody had ever been charged for. Admin-only, so never a self-service exploit,
  // but a support agent clicking "extend" was minting refundable balance.
  //
  // SEMANTICS CHOSEN: gifted months are recorded as sold at 100% off, and blended
  // into the rate the existing months are on. That is the honest reading of a gift
  // — those months cost the customer nothing, so nothing may prorate out of them —
  // and it is exact rather than blunt: the blend leaves the CASH VALUE of the
  // remaining window completely unchanged, so a customer who paid for 12 months and
  // was gifted a 13th still gets back precisely what those 12 paid months are worth
  // on a downgrade. Zeroing the whole term instead would confiscate what they paid;
  // leaving the rate alone is the money printer. Repeated gifts only ever dilute
  // toward 100, so no number of calls can raise the payout.
  //
  // A NEGATIVE `days` removes months rather than adding them, so there is nothing
  // to blend in: the customer keeps the rate they bought at over a shorter window,
  // which strictly reduces any future credit. Blending negative months would push
  // the rate the other way and over-credit what is left.
  const gifted = days > 0;
  const termPromoPercent = gifted
    ? prorateBlendPercent({
        currentPercent: resolveTermPromoPercent(server.termPromoPercent),
        currentMonths: remainingMonths(server.expiresAt, Date.now()),
        addedPercent: 100, // gifted: no cash changed hands for these months
        addedMonths: (days * 86400_000) / MS_PER_AVG_MONTH,
      })
    : resolveTermPromoPercent(server.termPromoPercent);

  await db.server.update({
    where: { id: serverId },
    data: { expiresAt: new Date(base + days * 86400_000), termPromoPercent },
  });
  await audit(
    admin.id,
    "admin.extend_server",
    `${serverId} ${days}d${gifted ? ` gifted (rate basis ${server.termPromoPercent ?? "null"}% -> ${termPromoPercent}% off)` : ""}`,
  );
  revalidatePath("/admin/subscriptions");
  return {};
}

/**
 * GRANDFATHER PROGRAM, admin manual path. `Server.grandfatheredRenewalCents`
 * (see its own doc comment, and lib/renewal-charge.ts's `PricedServer` field)
 * is set AUTOMATICALLY at order/resize time to freeze the price a server was
 * actually sold at. This is the OTHER way it gets set: a support agent
 * honoring an informal "you keep your old price" arrangement — after a price
 * increase, a plan/tier change that re-froze at the new rate, or any one-off
 * negotiated rate — for which there was previously no admin surface at all.
 *
 * Deliberately the SAME field, not a second one. It is already the single
 * override point `renewalCharge` reads instead of `plan.priceCents` /
 * `gamePlan.priceCents` — every renewal path (the automatic sweep, the
 * saved-card path, and `renewNow` above) already honors it. Adding a second
 * "locked price" field would mean deciding, inside that one shared formula,
 * which of two frozen rates wins — precisely the second-formula ambiguity
 * lib/renewal-charge.ts's own docstring warns never to introduce.
 *
 * Stored as a MONTHLY rate in the same units `plan.priceCents` /
 * `gamePlan.priceCents` already carry (every seeded GamePlan is
 * `termMonths: 1`, so "per month" and "per term" coincide for the vast
 * majority of game servers too).
 */
export async function adminSetGrandfatheredPrice(prev: any, formData: FormData): Promise<{ error?: string }> {
  const admin = await requireAdmin();
  const serverId = String(formData.get("serverId") ?? "");
  const raw = String(formData.get("priceDollars") ?? "").trim();
