export type AdminRenewNowResult =
  | {
      ok: true;
      /** Which rail(s) actually paid this renewal. */
      path: "wallet" | "wallet+card" | "card";
      walletCents: number;
      cardCents: number;
      totalCents: number;
      /** ISO date string — the new `expiresAt`. */
      newExpiry: string;
    }
  | { ok: false; error: string; code?: string };

/**
 * ADMIN-ONLY: force a specific server's renewal to happen right now, instead
 * of waiting for the automatic sweep (`billingSweep` -> `renewDueServer` in
 * worker/billing.ts) to reach it. Two real operational needs drive this
 * (2026-09-25 audit): verifying the wallet -> card fallback actually works
 * for a real customer — as of this audit there is exactly ONE historical
 * renewal in production that ever completed via the card leg, a $2.99
 * hosting-addon renewal on an internal test account, and zero VPS/game-server
 * plan renewals have ever been proven to go through it — and processing a
 * renewal a little early when it is operationally sensible (a customer's
 * period lapses in a few hours and support wants it settled now rather than
 * waiting on the sweep or a timezone-adjacent dunning cycle).
 *
 * Unlike `dueServers()` (worker/billing.ts), this deliberately does NOT
 * require `server.expiresAt` to have already passed — same allowance the
 * customer's own `renewNow` already has, and for the same reason: an early
 * renewal is a legitimate, deliberate decision here, not a bug to guard
 * against. See `renewServerImmediately`'s own doc comment for why an early
 * renewal is exactly as double-charge-safe as a late one.
 *
 * PRICING. The server row is read fresh with the SAME `include` shape
 * `dueServers()` uses — `plan`, `user`, `gamePlan`, `dedicatedIp` — and passed
 * straight into `renewServerImmediately`, which prices it with
 * `renewalCharge` directly off that raw row. This deliberately avoids
 * `renewNow`'s OTHER pattern just above in this file (rebuilding a fresh
 * literal `PricedServer`-shaped object): that pattern exists there only
 * because `renewNow` re-fetches `plan`/`gamePlan` separately from an
 * already-loaded server row, and building the object by hand is exactly how
 * that function's own comment says `annualDiscountPct` /
 * `grandfatheredRenewalCents` got silently dropped once, in production.
 * Passing the raw Prisma row straight through carries every column
 * automatically, including the two that bug lost, so it cannot recur here.
 *
 * MONEY MECHANICS. Not a third copy of the wallet/card split arithmetic — see
 * `renewServerImmediately`'s own doc comment (worker/billing.ts) for exactly
 * which real functions it reuses (`walletSplit`, `hasChargeableCard`,
 * `attemptCardRenewal`, `commitRenewal`) and why THAT function exists rather
 * than calling the sweep's `renewDueServer` directly here (short version:
 * `renewDueServer` silently no-ops for any server with `autoRenew` off, and
 * returns nothing a UI could show).
 *
 * SPEND CAP. Deliberately does NOT enforce the owner's spend cap
 * (`lib/spend-caps.ts`) the way the customer's own `renewNow` does. This
 * action stands in for the automatic sweep, which has never checked the
 * spend cap either — the cap is a customer self-service guard against their
 * OWN future voluntary spending, not a limit on collecting a bill that was
 * already going to come due regardless. An admin forcing that same charge a
 * little early should not be blocked by a control the sweep itself does not
 * honor.
 */
export async function adminRenewServerNow(serverId: string): Promise<AdminRenewNowResult> {
  // `requireAdmin()` alone, matching every sibling admin action in this file
  // (adminExtendServer / adminSetServerFree / adminSetGrandfatheredPrice) —
  // NOT `assertNotImpersonating()`. That guard exists for spend paths reachable
  // from the CUSTOMER portal while an admin wears a customer's identity; this
  // action only ever renders on `/admin/servers/[id]`, which already refuses to
  // render at all during impersonation (see CLAUDE.md), and `requireAdmin()`
  // itself already fails during impersonation because `currentUser()` resolves
  // to the impersonated (non-admin) target, not the real admin.
  const admin = await requireAdmin();

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
  });
  if (!server) return { ok: false, error: "Server not found." };
  if (server.isFree || !server.expiresAt) {
    return { ok: false, error: "This server is free or has no billing period — there is nothing to renew." };
  }

  // Same "one in-flight job per server" guard `serverAction` uses for the
  // customer-facing VM controls — a renewal racing a DELETE or MIGRATE job
  // could charge a customer for a server that is mid-teardown, or leave two
  // jobs contending for the same VM.
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) {
    return { ok: false, error: "Another operation is already running on this server. Wait for it to finish." };
  }

  // The SERVER OWNER (not necessarily the acting admin) determines the VAT/GST
  // rate, exactly like `renewNow` above.
  const taxCtx = await taxContextForUser(server.user);
  // Same shape `billingSweep()` builds once per sweep pass (worker/billing.ts);
  // built fresh here since this call renews exactly one server.
  const prices = {
    ipMonthlyCents: await dedicatedIpMonthlyCents(),
    extraDiskPerGbCents: await extraDiskPerGbCents(),
    backupPlusCents: await backupPlusMonthlyCents(),
    annualDiscountPct: await annualDiscountPct(),
  };
  const cfg = await dunningConfig();

  const result = await renewServerImmediately(server, {
    now: new Date(),
    cfg,
    prices,
    taxRatePercent: taxCtx.ratePercent,
    taxCountry: taxCtx.country,
  });

  if (!result.ok) {
    await audit(
      admin.id,
      "admin.renew_now",
      `${serverId} (${server.hostname}) FAILED — ${result.reason}: ${result.message}`,
    );
    return { ok: false, error: result.message, code: result.code };
  }

  await audit(
    admin.id,
    "admin.renew_now",
    `${serverId} (${server.hostname}) renewed via ${result.path} — wallet $${(result.walletCents / 100).toFixed(2)} + card $${(result.cardCents / 100).toFixed(2)} = $${(result.totalCents / 100).toFixed(2)}, new expiry ${result.newExpiry.toISOString().slice(0, 10)}`,
  );

  // Same post-charge bookkeeping `renewNow` runs for a customer-triggered
  // renewal — worker/billing.ts's own sweep never touches either of these,
  // they belong to an ATTRIBUTABLE renewal event, not the unattended pass.
  await maybeAlertBudget(server.userId);
  await accrueRecentCommissionsForCustomer(server.userId);

  // Mirrors renewNow's own UNPAID auto-restore: a successful admin-forced
  // payment on a suspended-unpaid server brings it back exactly the way the
  // customer's own payment would. Never for an abuse/admin suspension — see
  // `Server.suspendReason`'s own doc comment for why that check matters.
  if (server.status === "SUSPENDED" && server.suspendReason === "UNPAID") {
    const pendingUnsuspend = await db.job.count({
      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (pendingUnsuspend === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
  }

  revalidatePath(`/admin/servers/${serverId}`);
  revalidatePath("/admin/servers");
  revalidatePath("/admin/subscriptions");

  return {
    ok: true,
    path: result.path,
    walletCents: result.walletCents,
    cardCents: result.cardCents,
    totalCents: result.totalCents,
    newExpiry: result.newExpiry.toISOString(),
  };
}

export async function adminSetServerFree(serverId: string, isFree: boolean) {
  const admin = await requireAdmin();
  await db.server.update({
