// ---------- Impersonation (admin) ----------

export async function impersonateUser(userId: string) {
  const admin = await requireAdmin();
  const target = await db.user.findUnique({ where: { id: userId } });
  if (!target || target.role === "ADMIN") throw new Error("Cannot impersonate this account");
  // Through the shared writer so the row carries the admin's client IP
  // (docs/AUDIT-7D-2026-10-01.md F-15: every impersonation row had ip=NULL).
  // Written BEFORE the impersonation cookie is set so `recordAudit`'s own
  // "actingAdmin=" attribution stays off this row and `detail` remains exactly
  // the target email, as every reader of this action expects.
  await recordAudit(admin.id, "admin.impersonate_start", `${target.email}`);
  await setImpersonation(userId);
  redirect("/dashboard");
}

