/** Syncs every enabled node's own pool (not just the primary's) — a node's
 *  pool is only ever synced from its own provider (OVH/Hetzner), so this is
 *  the one admin action that needs to know about every node, not a single
 *  implicit one. */
export async function syncIpPool(): Promise<{ imported?: number; total?: number; error?: string }> {
  await requireAdmin();
  try {
    const nodes = await db.node.findMany({ where: { enabled: true }, select: { id: true } });
    let imported = 0;
    let total = 0;
    for (const n of nodes) {
      const r = await syncDedicatedIpPool(n.id);
      imported += r.imported;
      total += r.total;
    }
    revalidatePath("/admin/ips");
    return { imported, total };
  } catch (e: any) {
    return { error: String(e?.message ?? e).slice(0, 200) };
  }
}

export async function setIpReverse(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  await requireAdmin();
  const address = String(formData.get("address") ?? "");
  const reverse = String(formData.get("reverse") ?? "").trim();
  if (!address || !reverse) return { error: "Address and reverse required." };
  try {
    await setDedicatedReverse(address, reverse.endsWith(".") ? reverse : reverse + ".");
    revalidatePath("/admin/ips");
    return { ok: true };
  } catch (e: any) {
    return { error: String(e?.message ?? e).slice(0, 200) };
  }
}

