export async function serviceAction(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("service action: missing serverId");
  const p = (job.payload ?? {}) as { unit?: string; action?: string };
  const unit = String(p.unit ?? "");
  const action = String(p.action ?? "");
  assertService(unit);
  assert((SERVICE_ACTIONS as readonly string[]).includes(action), `Unsupported action: ${action}`);

  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });

  try {
    if (REAL) {
      const s = await sshServer(job.serverId);
      await withServerSsh(s, async (conn) => runService(conn, unit, action));
    }
    if (server) {
      await notify(
        server.userId,
        `${action[0].toUpperCase()}${action.slice(1)}ed ${unit}`,
        REAL ? `${unit} was ${action}ed on ${server.hostname}.` : `${unit} ${action} (sandbox — no real VM was touched).`,
        `/dashboard/servers/${job.serverId}?tab=control panel`
      );
    }
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 300);
    if (server) await notify(server.userId, `Could not ${action} ${unit}`, reason, `/dashboard/servers/${job.serverId}`);
    throw e; // let the worker mark the job FAILED/retry
  }
}
