import Link from "next/link";
import { notFound } from "next/navigation";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatusDot, Badge } from "@/components/ui/primitives";
import { OpsNav } from "@/components/admin/ops/OpsNav";
import { ServerOpsPanel } from "@/components/admin/ops/ServerOpsPanel";

export const dynamic = "force-dynamic";

export default async function OpsServerPage({ params }: { params: Promise<{ id: string }> }) {
  await requireArea("fleet");
  const { id } = await params;
  const s = await db.server.findUnique({
    where: { id },
    select: {
      id: true,
      hostname: true,
      status: true,
      vmid: true,
      ipAddress: true,
      sshPort: true,
      isFree: true,
      user: { select: { email: true } },
      node: { select: { name: true, publicIp: true } },
      gamePlan: { select: { gameFamily: true, name: true } },
      plan: { select: { name: true } },
      dedicatedIp: { select: { address: true } },
      jobs: { where: { status: { in: ["QUEUED", "RUNNING"] } }, select: { type: true, status: true }, take: 3 },
    },
  });
  if (!s) notFound();
  return (
    <div>
      <PageHeader title={s.hostname} sub={`${s.gamePlan ? `${s.gamePlan.name} (${s.gamePlan.gameFamily})` : s.plan.name} · ${s.user.email}`}>
        <Link className="btn-ghost py-1.5 text-sm" href={`/admin/servers/${s.id}`}>
          Server detail →
        </Link>
      </PageHeader>
      <OpsNav active="/admin/ops/servers" />
      <div className="mb-4 flex flex-wrap items-center gap-3 text-xs text-slate-400">
        <StatusDot status={s.status} />
        <span>node {s.node?.name ?? "primary"}</span>
        <span>vmid {s.vmid ?? "—"}</span>
        <span className="font-mono">{s.dedicatedIp ? s.dedicatedIp.address : `${s.ipAddress ?? "?"} · ssh ${s.node?.publicIp ?? ""}:${s.sshPort ?? "?"}`}</span>
        {s.isFree && <Badge tone="green">free</Badge>}
        {s.jobs.map((j, i) => (
          <Badge key={i} tone="amber">
            {j.type} {j.status.toLowerCase()}
          </Badge>
        ))}
      </div>
      <ServerOpsPanel serverId={s.id} />
    </div>
  );
}

